// The iOS entry point.
//
// Generated by `tauri ios init`, and then edited -- which is worth knowing
// before running that command again, because it would write this file back
// to the four lines it started as. The addition is the accessory-bar removal
// below; everything else is as generated.

#import <UIKit/UIKit.h>
#import <objc/runtime.h>

#include "bindings/bindings.h"

// ---------------------------------------------------------------------------
// The keyboard's form accessory bar
// ---------------------------------------------------------------------------
//
// The strip iOS puts between the keyboard and the page -- the one with the
// up/down chevrons and "Done" -- is WebKit's form assistant. It is there to
// step between the fields of a form, and this app has no forms in that sense:
// the composer is a single textarea, so the chevrons are permanently dimmed
// and the bar is a band of chrome sitting on top of the conversation for no
// purpose. On a phone that is a real amount of the screen.
//
// There is no web-side switch for it. No meta tag, no CSS, no attribute --
// the bar belongs to the native view that hosts the web content, so it has to
// be removed natively, and the way to do that is to override the getter that
// supplies it. That view is `WKContentView`, WebKit's private subview inside
// every WKWebView's scroll view, which is why this reaches for it by name:
// the class is not public API. This is the same approach Cordova, Capacitor
// and Ionic have all shipped for years, and it is the only one there is.
//
// The two things it costs, both worth stating plainly:
//
//   * "Done" goes with the bar, so dismissing the keyboard is now done by
//     tapping the conversation rather than by a button. WebKit blurs a
//     focused field on a tap outside it, so there is a way out; it is just
//     not a labelled one.
//   * A private class name is a thing App Review can object to. Nothing here
//     calls private *API* -- `inputAccessoryView` is UIResponder's, entirely
//     public -- and only the class is looked up by string, so the risk is low
//     and well-trodden. It is still a thing to remember if a submission is
//     ever rejected for something unexplained. There is no store listing yet
//     (docs/mobile-setup.md).
//
// Everything fails soft. A WebKit that no longer has this class, or no longer
// has this method, leaves the bar exactly where it is and the app runs
// normally -- there is no version of this that can stop the app from starting.

static id WherryNilAccessoryView(id self, SEL _cmd) { return nil; }

static void WherryHideFormAccessoryBar(void) {
  Class contentView = NSClassFromString(@"WKContentView");
  if (!contentView) {
    NSLog(@"[wherry] WKContentView not found; keyboard accessory bar left alone");
    return;
  }

  SEL selector = @selector(inputAccessoryView);
  Method method = class_getInstanceMethod(contentView, selector);
  if (!method) {
    NSLog(@"[wherry] inputAccessoryView not found; keyboard accessory bar left alone");
    return;
  }

  // class_addMethod first, and this ordering is the point rather than
  // defensiveness. `class_getInstanceMethod` walks up the superclass chain,
  // so `method` may well belong to UIResponder rather than to WKContentView
  // -- and replacing *its* implementation would take the accessory view away
  // from every responder in the process, which on iOS includes the keyboard's
  // own machinery. Adding the override lands it on WKContentView alone.
  // Adding fails only when WKContentView already defines the method itself,
  // in which case setting the implementation is safe for the same reason.
  if (class_addMethod(contentView, selector, (IMP)WherryNilAccessoryView,
                      method_getTypeEncoding(method))) {
    NSLog(@"[wherry] keyboard accessory bar hidden (override added)");
  } else {
    method_setImplementation(method, (IMP)WherryNilAccessoryView);
    NSLog(@"[wherry] keyboard accessory bar hidden (implementation replaced)");
  }
}

int main(int argc, char * argv[]) {
	// Before the app starts, so the first keyboard is already without a bar.
	// Class surgery, not instance surgery -- there is no web view yet, and
	// there does not need to be.
	WherryHideFormAccessoryBar();
	ffi::start_app();
	return 0;
}
